insert into public.question_bank (category, prompt, answer, variants, kind, curtain, value, enabled, youtube_id, vk_url, start_seconds, end_seconds, audio_url, audio_fx, image_url, picture, picture_spec, reveal_seconds, image_credit, image_license, image_page) values
  ('Нейросеть пересказала', 'Мальчика, живущего в чулане под лестницей, забирает в закрытый интернат великан. Там мальчик играет в командную игру на мётлах.', 'Гарри Поттер', array['Гарри Поттер и философский камень', 'Harry Potter']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Многосерийная хроника неудачных попыток взрослого курящего хищника поймать младшего; каждый раз хищник обещает, что ещё встретятся.', 'Ну, погоди!', array['Ну погоди']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Молодой наследник уходит из семьи после гибели отца, питается насекомыми в компании свина и суриката, а потом возвращается и смещает дядю.', 'Король Лев', array['The Lion King']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'После бани с друзьями мужчина улетает не в тот город, открывает своим ключом чужую квартиру по такому же адресу и знакомится с хозяйкой.', 'Ирония судьбы, или С лёгким паром!', array['Ирония судьбы', 'Ирония судьбы или с легким паром']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Семья улетает на Рождество в отпуск и забывает восьмилетнего сына. Мальчик тестирует бытовые ловушки на двух взрослых грабителях.', 'Один дома', array['Home Alone']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Демобилизованный молодой человек приезжает в Петербург к старшему родственнику, много ходит по городу и слушает «Наутилус Помпилиус».', 'Брат', array['Брат 1']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Дорогое пассажирское судно сталкивается со льдом. Молодой художник остаётся в воде, хотя на плавающей двери, по мнению зрителей, места хватало.', 'Титаник', array['Titanic']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Зелёный отшельник защищает своё болото от переселенцев и заодно спасает принцессу, у которой по вечерам меняется внешность.', 'Шрек', array['Shrek']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Мальчик переезжает жить за город с котом и собакой. Главный конфликт в посёлке — с местным почтальоном, который требует документы.', 'Трое из Простоквашино', array['Простоквашино', 'Каникулы в Простоквашино']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Несколько семей много сезонов выясняют, кому сидеть на одном неудобном железном кресле. Всё это время зима приближается.', 'Игра престолов', array['Game of Thrones']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Офисный программист выбирает таблетку правильного цвета и узнаёт, что его рабочее место, город и обед — ненастоящие.', 'Матрица', array['The Matrix']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Подросток на автомобиле с переделанной электрикой случайно мешает знакомству собственных родителей и потом всю неделю это исправляет.', 'Назад в будущее', array['Back to the Future']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Заведующий детским садом очень похож на опасного преступника. Он садится вместо него в колонию, чтобы найти пропавший старинный шлем.', 'Джентльмены удачи', '{}'::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Инженер собирает в квартире машину, из-за которой управдом попадает в XVI век, а грозный правитель — в Москву 1970-х.', 'Иван Васильевич меняет профессию', array['Иван Васильевич']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Робот из будущего прибывает в 1984 год, чтобы помешать появлению лидера сопротивления. Одежду он берёт у байкеров без спроса.', 'Терминатор', array['The Terminator']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Скромному экономисту во время круиза по ошибке накладывают гипс с ценным содержимым. Дома за этим гипсом охотятся контрабандисты.', 'Бриллиантовая рука', '{}'::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Учитель химии из Альбукерке после тяжёлого диагноза открывает очень незаконный малый бизнес вместе с бывшим учеником.', 'Во все тяжкие', array['Breaking Bad']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Группа специалистов проникает в сон наследника корпорации, чтобы внушить ему идею. Финальный вопрос фильма — упадёт ли волчок.', 'Начало', array['Inception']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Девочка в заброшенном парке развлечений устраивается работать в баню для духов, чтобы расколдовать родителей, превращённых в свиней.', 'Унесённые призраками', array['Spirited Away', 'Сэн и Тихиро']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Нейросеть пересказала', 'Фермер улетает в червоточину, чтобы найти людям новую планету, и передаёт дочери данные через книжную полку и часы.', 'Интерстеллар', array['Interstellar']::text[], 'text', false, 500, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
