  ('Логика с подвохом', 'На берёзе выросли три ветки, на каждой ветке — по три яблока. Сколько всего яблок?', 'Нисколько — на берёзе не растут яблоки', array['нисколько', 'ноль', '0', 'ни одного']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Петух сел на конёк крыши и снёс яйцо. В какую сторону скатится яйцо?', 'Никуда: петухи яиц не несут', array['никуда', 'петух не несёт яйца', 'петухи не несутся']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Сколько месяцев в году имеют 28 дней?', 'Все 12', array['12', 'двенадцать', 'все']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Что тяжелее: килограмм ваты или килограмм железа?', 'Одинаково', array['одинаково весят', 'ничего', 'поровну', 'они равны']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'В квадратной комнате в каждом углу сидит кошка, напротив каждой кошки сидят три кошки. Сколько всего кошек в комнате?', 'Четыре', array['4']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Как бросить мяч, чтобы он пролетел немного, остановился и сам вернулся к вам, ни обо что не ударившись?', 'Подбросить вверх', array['вверх', 'вертикально вверх']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Что принадлежит только вам, но другие пользуются этим гораздо чаще, чем вы сами?', 'Имя', array['ваше имя', 'моё имя']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Что становится тем больше, чем больше из него берут?', 'Яма', array['дыра']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Вы бежите марафон и обгоняете того, кто бежит последним. Каким вы теперь бежите?', 'Невозможно — последнего не обогнать', array['невозможно', 'так нельзя', 'никаким']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Сколько горошин может войти в обычный стакан?', 'Ни одной: горошины не ходят', array['ни одной', 'нисколько', 'ноль', '0']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Сколько земли в яме глубиной два метра, шириной два метра и длиной два метра?', 'Нисколько', array['ноль', '0', 'нет земли']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Что можно приготовить, но нельзя съесть?', 'Уроки', array['домашнее задание', 'домашку']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Электричка идёт на север, ветер дует на юг. В какую сторону летит дым от электрички?', 'Никуда: электрички дыма не дают', array['никуда', 'нисколько', 'у неё нет дыма']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Врач дал вам три таблетки и велел пить по одной каждые полчаса. Через сколько минут таблетки закончатся?', 'Через 60 минут', array['60', 'час', 'через час']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Два отца и два сына съели три яйца, каждому досталось по целому яйцу. Как так получилось?', 'Их было трое: дедушка, его сын и внук', array['трое', 'их трое', 'дедушка папа и внук', 'дед сын и внук']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Сколько зверей каждого вида взял с собой в ковчег Моисей?', 'Нисколько — ковчег строил Ной', array['нисколько', 'ноль', '0', 'ной']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Сколько раз можно вычесть десять из ста?', 'Один раз', array['1', 'один', 'однажды']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Кирпич весит один килограмм и ещё полкирпича. Сколько весит кирпич?', 'Два килограмма', array['2', '2 кг', 'два кг']::text[], 'text', false, 500, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Сколько будет, если тридцать разделить на половину и прибавить десять?', 'Семьдесят', array['70']::text[], 'text', false, 500, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Логика с подвохом', 'Сколько концов у трёх с половиной палок?', 'Восемь', array['8']::text[], 'text', false, 500, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Письмо П. А. Вяземскому, ноябрь 1825
  ('Кто это сказал?', '«Ай да ____, ай да сукин сын!» — так поэт похвалил себя в письме другу, закончив трагедию «Борис Годунов». Кто это написал?', 'Александр Пушкин', array['Пушкин', 'А. С. Пушкин']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Воспоминания актёров МХТ; «Моя жизнь в искусстве»
  ('Кто это сказал?', '«Не верю!» — этой фразой великий театральный режиссёр останавливал фальшиво игравших актёров. Кто он?', 'Константин Станиславский', array['Станиславский']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Витрувий, «Десять книг об архитектуре», кн. IX
  ('Кто это сказал?', '«Эврика!» — по легенде, с этим криком учёный выскочил из ванны и побежал по городу. Кто это был?', 'Архимед', array['Archimedes']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Радиопереговоры Apollo 11, 21 июля 1969
  ('Кто это сказал?', '«Это маленький шаг для человека, но гигантский скачок для человечества». Кто это сказал?', 'Нил Армстронг', array['Армстронг', 'Neil Armstrong']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Письмо М. Борну, 4 декабря 1926
  ('Кто это сказал?', '«Бог не играет в кости», — так в письме Максу Борну физик возражал против квантовой случайности. Кто это?', 'Альберт Эйнштейн', array['Эйнштейн', 'Einstein']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: В. Маяковский, «Послушайте!», 1914
  ('Кто это сказал?', '«Ведь, если звёзды зажигают — значит — это кому-нибудь нужно?» — строчка из стихотворения «Послушайте!». Чьё оно?', 'Владимир Маяковский', array['Маяковский']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Письмо Ал. П. Чехову, 11 апреля 1889
  ('Кто это сказал?', '«Краткость — сестра таланта», — написал в письме брату писатель. Кто?', 'Антон Чехов', array['Чехов', 'А. П. Чехов']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Интервью после матча Аргентина — Англия, 22 июня 1986
  ('Кто это сказал?', '«Немного головой ____ и немного рукой Бога», — объяснил футболист свой гол англичанам на чемпионате мира 1986 года. Кто?', 'Диего Марадона', array['Марадона', 'Maradona']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Пресс-конференция перед боем с С. Листоном, февраль 1964
  ('Кто это сказал?', '«Порхай как бабочка, жаль как пчела», — обещал боксёр перед боем с Сонни Листоном в 1964 году. Кто он?', 'Мохаммед Али', array['Али', 'Кассиус Клей', 'Muhammad Ali']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Письмо Р. Гуку, 5 февраля 1675/76
  ('Кто это сказал?', '«Если я видел дальше других, то потому, что стоял на плечах гигантов», — написал учёный своему сопернику Роберту Гуку. Кто это?', 'Исаак Ньютон', array['Ньютон', 'Isaac Newton']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Речь в Стэнфорде, 12 июня 2005 («Stay hungry, stay foolish»)
  ('Кто это сказал?', '«Оставайтесь голодными, оставайтесь безрассудными», — этими словами закончил речь перед выпускниками Стэнфорда в 2005 году основатель IT-компании. Кто?', 'Стив Джобс', array['Джобс', 'Steve Jobs']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: New York Journal, 2 июня 1897 (в оригинале «The report of my death was an exaggeration»)
  ('Кто это сказал?', '«Слухи о моей смерти сильно преувеличены», — ответил писатель журналисту, пришедшему узнать о его кончине. Кто это?', 'Марк Твен', array['Твен', 'Сэмюэл Клеменс', 'Mark Twain']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Интервью после полуфинала ЧМ-1990 ФРГ — Англия
  ('Кто это сказал?', '«Футбол — простая игра: 22 человека 90 минут гоняются за мячом, а в конце всегда побеждают немцы», — сказал английский нападающий после полуфинала ЧМ-1990. Кто?', 'Гари Линекер', array['Линекер', 'Gary Lineker']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: О. Уайльд, «Веер леди Уиндермир», 1892, акт I
  ('Кто это сказал?', '«Я могу устоять перед чем угодно, кроме искушения», — эта реплика из пьесы «Веер леди Уиндермир». Кто её автор?', 'Оскар Уайльд', array['Уайльд', 'Oscar Wilde']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Документальный сериал «Into the Universe with Stephen Hawking», Discovery, 2010
  ('Кто это сказал?', '«Я устроил вечеринку для путешественников во времени, но разослал приглашения только после неё. Никто не пришёл», — рассказал физик. Кто?', 'Стивен Хокинг', array['Хокинг', 'Stephen Hawking']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: J. B. Birks, «Rutherford at Manchester», 1962
  ('Кто это сказал?', '«Все науки делятся на две группы — физику и коллекционирование марок», — любил повторять физик, открывший атомное ядро. Кто это?', 'Эрнест Резерфорд', array['Резерфорд', 'Rutherford']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: С. Дали, «Дневник одного гения», 1964
  ('Кто это сказал?', '«Каждое утро, просыпаясь, я испытываю высшее наслаждение — быть собой», — в оригинале художник называет здесь своё имя. Кто это?', 'Сальвадор Дали', array['Дали', 'Salvador Dali']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: J. J. O’Neill, «Prodigal Genius: The Life of Nikola Tesla», 1944
  ('Кто это сказал?', '«Я любил эту голубку, как мужчина любит женщину», — признавался изобретатель асинхронного электродвигателя. Кто это?', 'Никола Тесла', array['Тесла', 'Nikola Tesla']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Р. Фейнман, «Характер физических законов», 1965, лекция 6
  ('Кто это сказал?', '«Думаю, я могу с уверенностью сказать, что квантовую механику не понимает никто», — сказал в лекциях лауреат Нобелевской премии по физике. Кто?', 'Ричард Фейнман', array['Фейнман', 'Richard Feynman']::text[], 'text', false, 500, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: F. Dyson, «Innovation in Physics», Scientific American, сентябрь 1958
  ('Кто это сказал?', '«Мы все согласны, что ваша теория безумна. Вопрос в том, достаточно ли она безумна, чтобы быть верной», — сказал датский физик Вольфгангу Паули. Кто?', 'Нильс Бор', array['Бор', 'Niels Bohr']::text[], 'text', false, 500, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Железная вышка посреди города, в очереди на лифт стояли час, наверху ветер. Похоже на недостроенную ЛЭП.', 'Эйфелева башня', array['Эйфелева', 'Eiffel Tower']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Зелёная тётя с факелом на острове. На экскурсию в корону очередь на месяцы вперёд.', 'Статуя Свободы', array['Statue of Liberty']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Письмо пришло мне сто раз через камин, а школу я так и не нашёл: на вокзале нет никакой платформы между девятой и десятой.', 'Гарри Поттер', array['Гарри Поттер и философский камень', 'Harry Potter']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Строители явно не пользовались уровнем. Все туристы вокруг стоят в странных позах, будто что-то подпирают.', 'Пизанская башня', array['Пизанская']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Три огромные треугольные кучи камней в пустыне, внутри тесно и душно, а у охраняющей их кошки отбит нос.', 'Пирамиды Гизы', array['пирамиды', 'египетские пирамиды', 'пирамида Хеопса']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Три часа ждали, чем кончится, а корабль всё равно утонул. На двери явно было место для двоих.', 'Титаник', array['Titanic']::text[], 'text', false, 100, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Дочитала до конца и плакала весь вечер. Глухонемой дворник, капризная барыня, лодка — больше ничего хорошего не запомнила.', 'Муму', '{}'::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Крыши нет, половины стен нет, сиденья тоже разобрали. Реставрацию не делали лет две тысячи.', 'Колизей', array['Колизеум', 'Colosseum']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Ничего не видно, одни туристы и какая-то женщина в раме.', 'Лувр', array['Louvre']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Самое глубокое озеро, а нормального пляжа нет. Вода ледяная даже в июле, нерпу видели только на магните.', 'Байкал', '{}'::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Улицы затоплены, такси только по воде и дорогие, а водитель ещё и пел всю дорогу.', 'Венеция', array['Venice']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Четыре тома, половина разговоров на французском, а один дуб описывают несколько страниц.', 'Война и мир', '{}'::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Шли по ней три часа, конца так и не увидели. Говорят, из космоса её не видно — и правильно.', 'Великая Китайская стена', array['Китайская стена']::text[], 'text', false, 200, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Белое здание красивое, но внутри просто гробница. И почему-то все фотографируются, будто держат купол за макушку.', 'Тадж-Махал', array['Тадж Махал']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Обещали книгу про Москву, а там кот ходит на задних лапах, чинит примус и стреляет. Подсолнечное масло теперь обхожу.', 'Мастер и Маргарита', '{}'::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Студент полкниги ходит по Петербургу и переживает. Старушкам не рекомендую.', 'Преступление и наказание', '{}'::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Фонтаны выключили на зиму. Золотой силач рвёт пасть льву — детям страшно.', 'Петергоф', array['Петродворец']::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Ходили весь день, не прошли и десятой части залов. Знаменитых котов в подвалах так и не показали.', 'Эрмитаж', '{}'::text[], 'text', false, 300, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Карабкались в Анды ради руин и лам. Кислорода мало, связи нет, обратно на поезде дорого.', 'Мачу-Пикчу', array['Мачу Пикчу', 'Machu Picchu']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Несколько камней стоят кругом в чистом поле, и всё. Ехали два часа из Лондона.', 'Стоунхендж', array['Stonehenge']::text[], 'text', false, 400, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  ('Угадай по отзыву', '★☆☆☆☆ Главный герой всю книгу скупает у помещиков какие-то бумаги. Второй том автор, видимо, сам и сжёг.', 'Мёртвые души', array['Мертвые души']::text[], 'text', false, 500, true, null, null, null, null, null, null, null, null, null, null, null, null, null),
  -- источник: Michael Jackson — Billie Jean, превью iTunes
  ('Звук наоборот', 'Звук наоборот № 1: известный хит звучит замедленно. Кто его исполняет?', 'Майкл Джексон', array['Michael Jackson', 'Джексон', 'Billie Jean']::text[], 'music', true, 100, true, null, null, 0, 20, 'https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview211/v4/dc/bc/8a/dcbc8a3e-4ce1-c00d-cc02-eda2212053c7/mzaf_8347559338388601510.plus.aac.p.m4a', 'slow', null, null, null, null, null, null, null),
  -- источник: Кино — Группа крови, превью iTunes
  ('Звук наоборот', 'Звук наоборот № 2: известный хит звучит замедленно. Кто его исполняет?', 'Кино', array['Виктор Цой', 'Цой', 'Kino', 'Группа крови']::text[], 'music', true, 100, true, null, null, 0, 20, 'https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview211/v4/16/fa/e1/16fae13f-5a75-56e9-beba-dbefd2275513/mzaf_11963562901282853013.plus.aac.p.m4a', 'slow', null, null, null, null, null, null, null),
  -- источник: Luis Fonsi & Daddy Yankee — Despacito, превью iTunes
  ('Звук наоборот', 'Звук наоборот № 3: известный хит звучит замедленно. Кто его исполняет?', 'Луис Фонси', array['Luis Fonsi', 'Фонси', 'Daddy Yankee', 'Дэдди Янки', 'Despacito']::text[], 'music', true, 100, true, null, null, 0, 20, 'https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview221/v4/0d/cb/ec/0dcbec41-5e9e-bd09-7cdd-fdff44acdf78/mzaf_17345185466754008149.plus.aac.p.m4a', 'slow', null, null, null, null, null, null, null),
  -- источник: Алла Пугачёва — Миллион алых роз, превью iTunes
